/* ---------------- Guidance vs actual ---------------- */
function guidance() {
  const sh = sheet('guidance'); const t = sh.tables[0]; const rows = t.rows.filter(Array.isArray); const col = n => t.columns.findIndex(c => new RegExp(n, 'i').test(c));
  const g = n => rows.map(r => typeof r[col(n)] === 'number' ? r[col(n)] : null); const lab = rows.map(r => r[0]);
  $('#blk-guidance').innerHTML = `<p class="lead sm">${esc(tr(t.notes[0] || ''))}</p>
   ${charts2([{id: 'gIfp', title: L('IFP: guidance range vs actual ($m)', 'IFP：指引区间与实际（百万美元）'), tip: 'IFP'}, {id: 'gRev', title: L('Revenue: guidance midpoint vs actual ($m)', '营收：指引中值与实际（百万美元）'), tip: 'Revenue', reins: 1}, {id: 'gEb', title: L('Adj. EBITDA: guidance midpoint vs actual ($m)', '调整后 EBITDA：指引中值与实际（百万美元）'), tip: 'Adj. EBITDA'}, {id: 'gGep', title: L('GEP: guidance midpoint vs actual ($m)', 'GEP：指引中值与实际（百万美元）'), tip: 'GEP'}])}
   ${tableBlock({title: L('Quarter by quarter', '逐季对比'), columns: t.columns, rows: t.rows, notes: t.notes.slice(1)}, {id: 'tGva', pre: sh.pre})}`;
  const range = (lo, hi, act, l1) => ({labels: lab, datasets: [{type: 'bar', label: L('Guidance range', '指引区间'), data: g(lo).map((v, i) => v == null ? null : [v, g(hi)[i]]), backgroundColor: C.band, barPercentage: .5, keep: 1},
      {type: 'line', label: L('Actual', '实际'), data: g(act), borderColor: C.acc, showLine: false, pointRadius: 6, pointHoverRadius: 8, pointStyle: 'rectRot', keep: 1}]});
  const mid = (gm, act) => ({labels: lab, datasets: [{type: 'bar', label: L('Guidance midpoint', '指引中值'), data: g(gm), backgroundColor: C.band}, {type: 'bar', label: L('Actual', '实际'), data: g(act), backgroundColor: C.acc}]});
  wireCard({id: 'gIfp', unit: '$m', build: () => { const r = range('ifp guide low', 'ifp guide high', 'ifp actual'); r.scales = {y: {beginAtZero: false}}; return r; }});
  wireCard({id: 'gRev', unit: '$m', reins: 1, build: () => mid('rev guide mid', 'rev actual')});
  wireCard({id: 'gEb', unit: '$m', build: () => mid('ebitda guide mid', 'ebitda actual')});
  wireCard({id: 'gGep', unit: '$m', build: () => mid('gep guide mid', 'gep actual')});
  charts.gIfp.options.plugins.tooltip.callbacks.label = c => Array.isArray(c.raw) ? `${L('Guide', '指引')}: $${fmt(c.raw[0])}–$${fmt(c.raw[1])}m` : `${L('Actual', '实际')}: ${money(c.raw)}`; charts.gIfp.update('none');
}
