  $$('#s-metrics a[href^="#metrics/"]:not([data-go])').forEach(a => a.addEventListener('click', e => { const k = a.getAttribute('href').split('/')[1]; if (location.hash === '#metrics/' + k) { e.preventDefault(); metricsJump(k); } }));
